class Solution {
public:
    bool isValid(string word) {
        int n = word.size();
        if (n < 3) return false;
        bool hasVowel = false, hasConsonant = false;
        string vowels = "aeiouAEIOU";
        for (char c : word) {
            if (c >= '0' && c <= '9') {
                continue;
            } else if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
                if (vowels.find(c) != string::npos) {
                    hasVowel = true;
                } else {
                    hasConsonant = true;
                }
            } else {
                return false;
            }
        }
        return hasVowel && hasConsonant;
    }
};
